action.mutation:
mutation CreateApprovedSupplier($payload: [ApprovedSupplierCreatePayloadInput!]!) {
  mutation: createApprovedSupplier(payload: $payload) { 
    id
    number
  }
}

mutation UpdateApprovedSupplier($payload: [ApprovedSupplierUpdatePayloadInput!]!) {
  mutation: updateApprovedSupplier(payload: $payload) { 
    id
    number
  }
}

mutation DeleteApprovedSupplier($payload: [ApprovedSupplierDeletePayloadInput!]!) {
  mutation: deleteApprovedSupplier(payload: $payload) { 
    id
    number
  }
}
